use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::Path};
const ROOT:&str="/home/ubuntu/src/zopro-perf-work/unreduced-gcd-consumer176";
fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn read(p:&str)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn main(){assert!(!Path::new(&format!("{ROOT}/review.json")).exists());let mut pin_counts=Vec::new();let mut receipts=0;
 for(phase,pinfile,planfile)in[("native","native-pins.json","native-plan.json"),("codegen","codegen-pins.json","codegen-plan.json"),("capture","capture-pins.json","capture-plan.json")]{let pins=read(&format!("{ROOT}/{pinfile}"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}pin_counts.push(pins.as_object().unwrap().len());let plan=read(&format!("{ROOT}/{planfile}"));for s in plan["steps"].as_array().unwrap(){let base=format!("{ROOT}/{phase}-runs/{}",s["name"].as_str().unwrap());let e=read(&format!("{base}/exit.json"));assert_eq!(e["returncode"],0);assert_eq!(e["success"],true);let c=read(&format!("{base}/command.json"));assert_eq!(&c["argv"].as_array().unwrap()[4..],s["argv"].as_array().unwrap());for stream in["stdout","stderr"]{assert_eq!(hash(&format!("{base}/{stream}.log")),e[format!("{stream}_sha256")].as_str().unwrap());}receipts+=1;}}
 let analysis=read(&format!("{ROOT}/analysis.json"));let jobs=read(&format!("{ROOT}/jobs.json"));let mut map=BTreeMap::new();for j in jobs.as_array().unwrap(){let name=j["name"].as_str().unwrap();let text=fs::read_to_string(format!("{ROOT}/capture-runs/{name}/stdout.log")).unwrap();let raw=text.lines().find_map(|l|l.strip_prefix("INVERSE ")).unwrap();let row:Value=serde_json::from_str(raw).unwrap();assert_eq!(&row,&analysis["all_raw_rows"][name]);map.insert(name.to_string(),row);}
 let mut agg=BTreeMap::<usize,Vec<f64>>::new();let mut selected=true;for c in analysis["comparisons"].as_array().unwrap(){let field=c["field"].as_str().unwrap();let w=c["workers"].as_u64().unwrap();let mut ratios=Vec::new();for b in 0..31{let off=map[&format!("b{b:02}-{field}-w{w}-OFF")]["wall_ns_per_inverse_per_worker"].as_f64().unwrap();let on=map[&format!("b{b:02}-{field}-w{w}-ON")]["wall_ns_per_inverse_per_worker"].as_f64().unwrap();ratios.push(on/off);agg.entry(b).or_default().push(on/off);}let wins=ratios.iter().filter(|x|**x<1.).count();ratios.sort_by(f64::total_cmp);for(k,index)in[("median",15),("lower",9),("upper",21)]{assert_eq!(c["ratio"][k].as_f64().unwrap(),ratios[index]);}assert_eq!(c["ratio"]["wins"],wins);let nonreg=ratios[21]<=1.02;let required=field=="Fq"&&[1,32].contains(&w);let gain=ratios[21]<1.&&wins>=21;selected&=nonreg&&(!required||gain);}
 let mut ratios=agg.values().map(|v|(v.iter().map(|x|x.ln()).sum::<f64>()/6.).exp()).collect::<Vec<_>>();let wins=ratios.iter().filter(|x|**x<1.).count();ratios.sort_by(f64::total_cmp);assert_eq!(analysis["equal_log_aggregate"]["median"].as_f64().unwrap(),ratios[15]);assert_eq!(analysis["equal_log_aggregate"]["upper"].as_f64().unwrap(),ratios[21]);selected&=ratios[21]<1.&&wins>=21&&analysis["diagnostic_quality_passed"]==true;assert_eq!(analysis["selected_for_G1_G2_callers"],selected);
 let codegen=read(&format!("{ROOT}/codegen.json"));assert_eq!(codegen["actual_consumer_sha256"],hash(&format!("{ROOT}/native/consumer")));let audit=read(&format!("{ROOT}/source-audit.json"));assert_eq!(audit["snapshot_originals_exact"],176);
 let out=json!({"review_passed":true,"pin_populations":pin_counts,"successful_receipts":receipts,"raw_complete_process_rows":map.len(),"paired_comparisons_reconstructed":6,"blocks":31,"selected_for_G1_G2_callers":selected,"analysis_sha256":hash(&format!("{ROOT}/analysis.json")),"same_binary_sha256":hash(&format!("{ROOT}/native/consumer")),"production_unchanged":true,"canonical_unchanged":35181,"new_proofs":0,"new_SDK_requests":0,"goal_complete":false,"limits":"Reconstructs raw process rows, paired estimates/decision, source/executable/receipt hashes and saved diagnostic qualification. Does not rerun arithmetic, recordings, decoders, or independently parse every PMU/perf ownership record."});fs::write(format!("{ROOT}/review.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Offline reader PASS:{receipts} receipts/{} process rows; all6 paired estimates/aggregate/selection reconstructed",map.len());}
